-- =====================================================================
-- Northward Retail Inc. (FICTIONAL COMPANY) - training dataset for MySQL 8
-- CLEAN database: schema + all data (about 16 MB)
-- Run the whole file once. It drops and recreates the database `northward`.
-- =====================================================================
SET NAMES utf8mb4;
DROP DATABASE IF EXISTS northward;
CREATE DATABASE northward CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE northward;
SET FOREIGN_KEY_CHECKS = 0;
SET autocommit = 0;

CREATE TABLE dim_date (
  full_date        DATE         NOT NULL PRIMARY KEY,
  year             SMALLINT     NOT NULL,
  quarter          CHAR(2)      NOT NULL,
  month_num        TINYINT      NOT NULL,
  month_name       VARCHAR(10)  NOT NULL,
  month_short      CHAR(3)      NOT NULL,
  month_label      CHAR(7)      NOT NULL,
  week_of_year     TINYINT      NOT NULL,
  day_of_month     TINYINT      NOT NULL,
  day_of_week_num  TINYINT      NOT NULL,
  day_name         VARCHAR(10)  NOT NULL,
  is_weekend       TINYINT      NOT NULL,
  is_holiday       TINYINT      NOT NULL,
  holiday_name     VARCHAR(60)  NULL,
  retail_event     VARCHAR(30)  NULL
);

CREATE TABLE stores (
  store_id     INT          NOT NULL PRIMARY KEY,
  store_name   VARCHAR(60)  NOT NULL,
  city         VARCHAR(40)  NOT NULL,
  province     CHAR(2)      NOT NULL,
  region       VARCHAR(20)  NOT NULL,
  store_type   VARCHAR(20)  NOT NULL,
  open_date    DATE         NOT NULL,
  square_feet  INT          NULL
);

CREATE TABLE sales_reps (
  sales_rep_id  INT          NOT NULL PRIMARY KEY,
  first_name    VARCHAR(40)  NOT NULL,
  last_name     VARCHAR(40)  NOT NULL,
  store_id      INT          NOT NULL,
  hire_date     DATE         NOT NULL,
  FOREIGN KEY (store_id) REFERENCES stores(store_id)
);

CREATE TABLE customers (
  customer_id     INT          NOT NULL PRIMARY KEY,
  first_name      VARCHAR(40)  NOT NULL,
  last_name       VARCHAR(40)  NOT NULL,
  email           VARCHAR(100) NOT NULL,
  phone           VARCHAR(20)  NOT NULL,
  age_group       VARCHAR(10)  NOT NULL,
  city            VARCHAR(40)  NOT NULL,
  province        CHAR(2)      NOT NULL,
  region          VARCHAR(20)  NOT NULL,
  signup_date     DATE         NOT NULL,
  signup_channel  VARCHAR(10)  NOT NULL,
  loyalty_tier    VARCHAR(10)  NOT NULL
);

CREATE TABLE products (
  product_id    INT            NOT NULL PRIMARY KEY,
  product_name  VARCHAR(80)    NOT NULL,
  category      VARCHAR(30)    NOT NULL,
  sub_category  VARCHAR(30)    NOT NULL,
  brand         VARCHAR(30)    NOT NULL,
  unit_cost     DECIMAL(10,2)  NOT NULL,
  list_price    DECIMAL(10,2)  NOT NULL,
  launch_date   DATE           NOT NULL
);

CREATE TABLE campaigns (
  campaign_id        INT            NOT NULL PRIMARY KEY,
  campaign_name      VARCHAR(60)    NOT NULL,
  marketing_channel  VARCHAR(20)    NOT NULL,
  start_date         DATE           NOT NULL,
  end_date           DATE           NOT NULL,
  budget             DECIMAL(12,2)  NOT NULL
);

CREATE TABLE orders (
  order_id        INT          NOT NULL PRIMARY KEY,
  customer_id     INT          NOT NULL,
  store_id        INT          NOT NULL,
  sales_rep_id    INT          NULL,
  order_date      DATE         NOT NULL,
  ship_date       DATE         NULL,
  delivery_date   DATE         NULL,
  channel         VARCHAR(10)  NOT NULL,
  payment_method  VARCHAR(20)  NOT NULL,
  campaign_id     INT          NULL,
  order_status    VARCHAR(12)  NOT NULL,
  FOREIGN KEY (customer_id)  REFERENCES customers(customer_id),
  FOREIGN KEY (store_id)     REFERENCES stores(store_id),
  FOREIGN KEY (sales_rep_id) REFERENCES sales_reps(sales_rep_id),
  FOREIGN KEY (campaign_id)  REFERENCES campaigns(campaign_id),
  FOREIGN KEY (order_date)   REFERENCES dim_date(full_date),
  INDEX idx_orders_date (order_date)
);

CREATE TABLE order_items (
  order_item_id  INT            NOT NULL PRIMARY KEY,
  order_id       INT            NOT NULL,
  product_id     INT            NOT NULL,
  quantity       INT            NOT NULL,
  unit_price     DECIMAL(10,2)  NOT NULL,
  discount_pct   TINYINT        NOT NULL,
  line_total     DECIMAL(12,2)  NOT NULL,
  FOREIGN KEY (order_id)   REFERENCES orders(order_id),
  FOREIGN KEY (product_id) REFERENCES products(product_id)
);

CREATE TABLE returns (
  return_id          INT            NOT NULL PRIMARY KEY,
  order_item_id      INT            NOT NULL,
  return_date        DATE           NOT NULL,
  quantity_returned  INT            NOT NULL,
  return_reason      VARCHAR(30)    NOT NULL,
  refund_amount      DECIMAL(12,2)  NOT NULL,
  FOREIGN KEY (order_item_id) REFERENCES order_items(order_item_id)
);

CREATE TABLE targets (
  target_id       INT            NOT NULL PRIMARY KEY,
  target_month    DATE           NOT NULL,
  region          VARCHAR(20)    NOT NULL,
  category        VARCHAR(30)    NOT NULL,
  revenue_target  DECIMAL(12,2)  NOT NULL
);

-- ---------- dim_date (1,096 rows)
COMMIT;

-- ---------- stores (45 rows)
COMMIT;

-- ---------- sales_reps (149 rows)
COMMIT;

-- ---------- customers (20,000 rows)
COMMIT;

-- ---------- products (300 rows)
COMMIT;

-- ---------- campaigns (30 rows)
COMMIT;

-- ---------- orders (55,781 rows)
COMMIT;

-- ---------- order_items (138,648 rows)
COMMIT;

-- ---------- returns (8,915 rows)
COMMIT;

-- ---------- targets (1,080 rows)
COMMIT;

SET FOREIGN_KEY_CHECKS = 1;
SET autocommit = 1;
SELECT 'Northward clean database loaded' AS status;
